/* MODULE kh01 · Bước 2 Hiểu khách hàng · Phân khúc: chia thị trường theo nhu cầu, không theo tuổi
   9 bài × 7 câu. Thương hiệu được nêu như ví dụ công khai; mọi con số là MINH HOẠ và tự khớp nhau. */
BAI_ADD({ mod:'kh01', lessons:[

/* ------------------------------------------------------------------ 01 */
{ id:'B:kh01-01', skill:'insight', read:'6 phút', t:'Hai khách cùng 28 tuổi, cùng lương — sao mua hai kiểu khác hẳn nhau?',
  situation:'Một chuỗi cà phê ở TP.HCM chia khách thành "nữ 22–30 tuổi, văn phòng". Trong tệp này có Linh, ghé lúc 7h30, mua mang đi trong 3 phút, chỉ cần đậm và nhanh; và Trang, ngồi 2 tiếng chiều thứ Bảy với laptop, cần ổ cắm và wifi. Cùng tuổi, cùng nghề, cùng thu nhập — nhưng nếu quán chiều theo một người thì làm hỏng trải nghiệm của người kia.',
  concept:{ name:'Phân khúc theo nhu cầu, không theo nhân khẩu học',
    body:'Tuổi, giới tính, thu nhập dễ đo nên hay được dùng để chia khách. Nhưng chúng chỉ là <b>mô tả</b>, không phải <b>lý do mua</b>. Hai người cùng nhân khẩu học có thể cần những thứ trái ngược; hai người khác tuổi lại có thể cần y hệt nhau. Phân khúc có ích khi mỗi nhóm cần một cách phục vụ khác: sản phẩm khác, giá khác, kênh khác, thông điệp khác. Nhân khẩu học chỉ nên dùng ở bước sau: để tìm và tiếp cận nhóm nhu cầu đã chọn.' },
  example:'Quán đếm hoá đơn một tuần: khoảng 60% là "mua nhanh mang đi" trước 9h, 25% là "ngồi làm việc" buổi chiều, 15% là "hẹn gặp" buổi tối. Trong nhóm mua nhanh có cả sinh viên 20 tuổi lẫn anh quản lý 45 tuổi. Chia theo nhu cầu, quán quyết định: quầy lấy nhanh riêng cho buổi sáng, khu bàn dài có ổ cắm cho buổi chiều. Chia theo tuổi thì không nói được hai quyết định đó.',
  takeaway:'Chia khách theo điều họ cần làm, rồi mới dùng tuổi và nơi ở để tìm họ.',
  apply:'Chọn một quán bạn hay ghé. Kể ra hai nhóm khách có cùng độ tuổi nhưng cần quán phục vụ khác nhau, trong 60 giây.',
  mistakes:['Mở brief bằng "nữ 25–35, thu nhập khá" rồi coi như đã hiểu khách.','Gộp mọi người cùng tuổi vào một thông điệp dù họ mua vì lý do khác nhau.'],
  q:[
  { type:'mcq', stem:'Đoán trước: Linh (mua mang đi buổi sáng) và Trang (ngồi làm việc chiều thứ Bảy) nên được xếp thế nào?',
    options:[{k:'a',t:'Cùng một phân khúc vì cùng tuổi, cùng nghề, cùng thu nhập'},{k:'b',t:'Hai phân khúc khác nhau vì cần quán phục vụ theo hai cách'},
             {k:'c',t:'Chưa chia được cho tới khi biết thêm quê quán và tình trạng hôn nhân của hai người'},{k:'d',t:'Bỏ Trang vì ngồi lâu, doanh thu mỗi giờ trên chỗ ngồi thấp'}],
    answer:'b', why:{a:'Giống nhau về mô tả nhưng khác nhau về nhu cầu; một cách phục vụ không vừa cả hai.',
      b:'Đúng. Phân khúc có ích khi mỗi nhóm cần sản phẩm, không gian hay thông điệp khác nhau.',
      c:'Thêm biến nhân khẩu học không làm rõ nhu cầu; hành vi ở quán đã đủ để thấy họ khác nhau.',
      d:'Chọn phục vụ ai là bước sau; trước hết phải thấy đây là hai nhóm khác nhau.'} },
  { type:'mcq', stem:'Sếp muốn chạy một chiến dịch cho "nữ 22–30 văn phòng". Bạn đề xuất sửa gì trước khi làm nội dung?',
    options:[{k:'a',t:'Giữ nguyên, chỉ thu hẹp tuổi xuống 25–28 cho tệp chính xác hơn'},{k:'b',t:'Thêm tiêu chí thu nhập trên 15 triệu và độ tuổi hẹp hơn để lọc đúng người có tiền chi tiêu'},
             {k:'c',t:'Tách theo dịp: mua nhanh buổi sáng và ngồi làm việc buổi chiều, mỗi nhóm một thông điệp riêng'},{k:'d',t:'Đổi sang nam 22–30 vì nhóm này ít bị đối thủ nhắm tới'}],
    answer:'c', why:{a:'Thu hẹp tuổi vẫn gộp hai nhu cầu trái ngược vào một thông điệp.',
      b:'Thu nhập không phân biệt được người cần nhanh với người cần chỗ ngồi.',
      c:'Đúng. Mỗi dịp cần một lời hứa khác: "lấy trong 3 phút" và "ngồi thoải mái cả chiều".',
      d:'Đổi giới tính vẫn là chia theo mô tả, không trả lời được khách cần gì.'} },
  { type:'mcq', stem:'Vì sao nhân khẩu học vẫn được dùng nhiều dù không giải thích lý do mua?',
    options:[{k:'a',t:'Vì nó dễ đo và dễ nhắm trên nền tảng quảng cáo'},{k:'b',t:'Vì nghiên cứu đã chứng minh tuổi quyết định hầu hết hành vi mua hàng tiêu dùng'},
             {k:'c',t:'Vì khách hàng Việt Nam mua theo nhóm tuổi rõ rệt hơn nước khác'},{k:'d',t:'Vì phân khúc theo nhu cầu chỉ dùng được cho doanh nghiệp lớn'}],
    answer:'a', why:{a:'Đúng. Tiện đo, tiện nhắm là lý do; đó là công cụ tìm người, không phải công cụ hiểu người.',
      b:'Tuổi có tương quan với vài hành vi, nhưng hiếm khi là nguyên nhân chính của lựa chọn.',
      c:'Không có căn cứ; khác biệt nhu cầu trong cùng độ tuổi xuất hiện ở mọi thị trường.',
      d:'Quán nhỏ cũng chia theo dịp được — chỉ cần đếm hoá đơn theo giờ.'} },
  { type:'calc', stem:'Một tuần quán có 2.400 hoá đơn, 60% là mua mang đi trước 9h. Có bao nhiêu hoá đơn thuộc nhóm "mua nhanh buổi sáng"?',
    unit:'hoá đơn', ans:1440, tol:1, wrong:[[960,'SAI_MAU_SO'],[4000,'SAI_TINH_TOAN']], errors:['SAI_MAU_SO','SAI_TINH_TOAN'],
    steps:['Số hoá đơn nhóm = tổng hoá đơn × tỉ lệ nhóm.','2.400 × 60% = <b>1.440</b> hoá đơn.'] },
  { type:'mcq', stem:'Tình huống mới: một thương hiệu sữa hạt thấy người mua gồm mẹ bỉm 30 tuổi, dân gym 24 tuổi và người ăn chay 55 tuổi. Cách chia nào dùng được nhất?',
    options:[{k:'a',t:'Chia ba nhóm tuổi 20–30, 30–45 và trên 45 để đo cho dễ'},{k:'b',t:'Chỉ tập trung mẹ bỉm vì phụ nữ quyết định phần lớn chi tiêu gia đình'},
             {k:'c',t:'Chia theo nhu cầu: bổ sung đạm, thay sữa bò, bữa sáng cho con'},{k:'d',t:'Gộp chung vì ai cũng uống sữa hạt nên thông điệp chung là đủ dùng'}],
    answer:'c', why:{a:'Nhóm tuổi không trùng với lý do mua; người 55 tuổi và 24 tuổi có thể cùng cần thay sữa bò.',
      b:'Chọn một nhóm là bước sau; lý do "phụ nữ chi tiêu" không mô tả nhu cầu nào.',
      c:'Đúng. Mỗi nhu cầu dẫn tới công thức, bao bì và lời hứa khác nhau.',
      d:'Thông điệp chung nói với mọi người thì không chạm được lý do riêng của ai.'} },
  { type:'mcq', stem:'Khi nào nhân khẩu học THỰC SỰ là cách chia đúng?',
    options:[{k:'a',t:'Khi thương hiệu mới ra mắt và chưa có dữ liệu gì về khách hàng'},{k:'b',t:'Khi tuổi hoặc giới trực tiếp tạo ra nhu cầu khác, như tã theo cân nặng bé'},
             {k:'c',t:'Khi ngân sách nhỏ nên cần tệp hẹp, dễ nhắm chính xác trên Facebook'},{k:'d',t:'Khi đối thủ lớn trong ngành đang chia theo tuổi và làm khá hiệu quả'}],
    answer:'b', why:{a:'Chưa có dữ liệu thì đi hỏi và quan sát; nhân khẩu học không thay được hiểu biết đó.',
      b:'Đúng. Khi đặc điểm nhân khẩu học chính là nguồn gốc nhu cầu, chia theo nó là chia theo nhu cầu.',
      c:'Tệp hẹp để nhắm là chuyện tiếp cận, không phải lý do chọn cách chia.',
      d:'Chép cách chia của đối thủ khiến bạn đánh cùng một trận với họ.'} },
  { type:'mcq', stem:'Dấu hiệu nào cho thấy một cách phân khúc đang VÔ DỤNG?',
    options:[{k:'a',t:'Mỗi nhóm có quy mô khác nhau, có nhóm lớn gấp đôi nhóm kia'},{k:'b',t:'Các nhóm được đặt tên hấp dẫn nhưng khó đo chính xác bằng số liệu bán hàng'},
             {k:'c',t:'Có một nhóm hiện chưa mua sản phẩm của công ty'},{k:'d',t:'Chia xong, mọi nhóm vẫn nhận cùng sản phẩm, giá và thông điệp'}],
    answer:'d', why:{a:'Quy mô chênh nhau là bình thường; không phải dấu hiệu vô dụng.',
      b:'Khó đo là một vấn đề, nhưng chưa chắc vô dụng nếu nó dẫn tới quyết định khác.',
      c:'Nhóm chưa mua có thể là cơ hội, không phải lỗi phân khúc.',
      d:'Đúng. Phân khúc tồn tại để khác cách làm; nếu không có gì thay đổi, nó chỉ là bảng phân loại.'} }
  ] },

/* ------------------------------------------------------------------ 02 */
{ id:'B:kh01-02', skill:'insight', read:'7 phút', t:'Bán bánh trung thu: chia khách theo tuổi hay theo dịp mua?',
  situation:'Một tiệm bánh ở Hà Nội chuẩn bị mùa Trung thu với 3.000 hộp. Năm ngoái họ chạy quảng cáo cho "nữ 30–50 tuổi" và bán đều, nhưng cuối mùa còn tồn gần 600 hộp loại 4 bánh giá 450.000đ, trong khi hộp 2 bánh 180.000đ hết từ tuần thứ hai. Chủ tiệm hỏi: năm nay nên làm gì khác?',
  concept:{ name:'Phân khúc theo dịp dùng (occasion)',
    body:'Cùng một người có thể mua bánh trung thu cho ba dịp khác nhau: <b>biếu sếp, đối tác</b> (cần hộp sang, giao tận nơi, hoá đơn), <b>mang về quê</b> (cần hộp vừa, bền khi đi xa), <b>ăn trong nhà</b> (cần bánh lẻ, giá mềm). Mỗi dịp có tiêu chí chọn khác, nên chia theo dịp giúp quyết định mẫu hộp, giá, kênh bán và thời điểm. Dịp dùng đặc biệt hữu ích với ngành hàng theo mùa, quà tặng, đồ uống, ăn uống — nơi "khi nào, cho ai, để làm gì" quyết định lựa chọn hơn là "tôi bao nhiêu tuổi".' },
  example:'Tiệm xem lại đơn năm ngoái: đơn hộp 4 bánh chủ yếu tới từ công ty đặt số lượng, và đỉnh rơi vào 10 ngày trước rằm. Hộp 2 bánh do cá nhân mua ăn và biếu nhẹ. Năm nay tiệm tách: dịp "biếu doanh nghiệp" bán qua gọi điện, nhận đơn từ sớm, sản xuất theo đơn; dịp "ăn nhà" bán bánh lẻ trên sàn. Tồn kho hộp lớn giảm vì không làm sẵn theo cảm tính nữa.',
  takeaway:'Hỏi "mua vào dịp nào, cho ai" trước khi hỏi "người mua bao nhiêu tuổi".',
  apply:'Chọn một sản phẩm quà tặng. Kể ra ba dịp mua và mỗi dịp khách cần gì khác nhau, trong 60 giây.',
  mistakes:['Một hộp, một mức giá, một thông điệp cho mọi dịp mua.','Tưởng người biếu và người ăn là hai người khác nhau, trong khi thường là cùng một người ở hai dịp.'],
  q:[
  { type:'mcq', stem:'Đoán trước: vì sao hộp 450.000đ tồn còn hộp 180.000đ hết sớm, dù cùng chạy cho "nữ 30–50"?',
    options:[{k:'a',t:'Hai hộp phục vụ hai dịp khác nhau nhưng được bán như một'},{k:'b',t:'Nữ 30–50 tuổi nhạy cảm về giá nên luôn chọn hộp rẻ hơn trong mọi hoàn cảnh'},
             {k:'c',t:'Hộp 4 bánh mẫu mã xấu nên không ai muốn mua biếu'},{k:'d',t:'Quảng cáo chạy thiếu ngân sách ở tuần cuối mùa'}],
    answer:'a', why:{a:'Đúng. Hộp lớn thuộc dịp biếu doanh nghiệp, cần kênh và thời điểm khác; bán chung với dịp ăn nhà thì lệch.',
      b:'Cùng người đó vẫn mua hộp đắt khi đi biếu; giá không phải lý do duy nhất.',
      c:'Không có dữ kiện về mẫu mã; dữ kiện chỉ ra kênh và thời điểm sai.',
      d:'Tăng tiền quảng cáo sai dịp chỉ đốt thêm tiền.'} },
  { type:'mcq', stem:'Năm nay bạn chọn cách bán hộp 4 bánh thế nào?',
    options:[{k:'a',t:'Giảm giá xuống 350.000đ để cạnh tranh với hộp nhỏ'},{k:'b',t:'Nhận đơn doanh nghiệp sớm, giao tận nơi, xuất hoá đơn, làm theo đơn'},
             {k:'c',t:'Chạy quảng cáo mạnh hơn cho nữ 30–50 tuổi ở các quận nội thành đông dân cư'},{k:'d',t:'Bỏ hẳn hộp 4 bánh vì năm ngoái tồn nhiều nhất'}],
    answer:'b', why:{a:'Giảm giá không sửa được việc bán sai kênh, sai thời điểm; chỉ mất lãi.',
      b:'Đúng. Phục vụ đúng tiêu chí của dịp biếu doanh nghiệp: sớm, tận nơi, có hoá đơn.',
      c:'Nhắm lại đúng tệp cũ theo tuổi thì lặp lại kết quả cũ.',
      d:'Hộp lớn vẫn có dịp mua riêng; bỏ đi là bỏ phần doanh thu biếu doanh nghiệp.'} },
  { type:'calc', stem:'Năm ngoái tiệm làm 1.500 hộp 4 bánh và tồn 600 hộp. Tỉ lệ bán hết (sell-through) của hộp 4 bánh là bao nhiêu phần trăm?',
    unit:'%', ans:60, tol:0.1, wrong:[[40,'NHAM_TI_LE_ROI'],[20,'SAI_MAU_SO']], errors:['NHAM_TI_LE_ROI','SAI_MAU_SO'],
    steps:['Số hộp bán được = 1.500 − 600 = 900.','Tỉ lệ bán hết = 900 ÷ 1.500 = <b>60%</b>.'] },
  { type:'mcq', stem:'Tình huống mới: một hãng nước tăng lực thấy khách mua vào ba dịp — trước ca đêm, trước buổi tập, khi lái xe đường dài. Việc nên làm với nhận định này?',
    options:[{k:'a',t:'Gom lại thành "nam 18–35" vì phần lớn người mua ở cả ba dịp là nam'},{k:'b',t:'Chỉ chọn dịp đông nhất và bỏ hẳn hai dịp còn lại ngay từ đầu'},
             {k:'c',t:'Đặt hàng ở điểm bán gắn với từng dịp: trạm dừng, phòng tập, cửa hàng gần xưởng'},{k:'d',t:'Đổi công thức cho từng dịp ngay lập tức'}],
    answer:'c', why:{a:'Gom về giới tính làm mất thông tin quý nhất: họ uống ở đâu, lúc nào.',
      b:'Có thể ưu tiên sau khi ước lượng quy mô; bỏ ngay là quá sớm.',
      c:'Đúng. Dịp dùng cho biết khách ở đâu khi cần — quyết định kênh và điểm bán.',
      d:'Đổi công thức tốn kém; thường thay kênh và thông điệp trước là đủ.'} },
  { type:'mcq', stem:'Điểm mạnh riêng của phân khúc theo dịp so với phân khúc theo người là gì?',
    options:[{k:'a',t:'Nó cho biết khi nào và ở đâu nhu cầu xuất hiện, để đặt hàng và nói đúng lúc'},{k:'b',t:'Nó không cần bất kỳ dữ liệu nào vì dịp dùng ai cũng đoán được'},
             {k:'c',t:'Nó thay thế hoàn toàn việc tìm hiểu tâm lý khách'},{k:'d',t:'Nó chỉ dùng được cho sản phẩm bán theo mùa như bánh trung thu, mứt Tết và quà Noel'}],
    answer:'a', why:{a:'Đúng. Dịp gắn với thời điểm và bối cảnh, nên dẫn thẳng tới quyết định kênh, lịch và thông điệp.',
      b:'Dịp dùng phải được kiểm bằng đơn hàng, giờ mua, lời khách kể; đoán dễ sai.',
      c:'Dịp dùng bổ sung chứ không thay việc hiểu động cơ.',
      d:'Cà phê, nước uống, đồ ăn nhanh đều chia theo dịp trong ngày được.'} },
  { type:'mcq', stem:'Một người vừa mua hộp biếu sếp vừa mua bánh lẻ ăn ở nhà. Nói "người này thuộc phân khúc nào" là sai ở chỗ nào?',
    options:[{k:'a',t:'Không sai, phải xếp họ vào nhóm chi tiêu nhiều nhất'},{k:'b',t:'Sai vì một người chỉ nên thuộc đúng một phân khúc theo độ tuổi của họ'},
             {k:'c',t:'Sai vì cần hỏi thêm thu nhập của họ mới xếp nhóm được'},{k:'d',t:'Theo dịp, cùng một người rơi vào hai phân khúc tuỳ lúc mua'}],
    answer:'d', why:{a:'Xếp theo mức chi làm mất thông tin: hai lần mua cần hai cách phục vụ.',
      b:'Chính cách nghĩ "một người – một nhóm" làm tiệm bán sai.',
      c:'Thu nhập không thay đổi việc họ cần hai thứ khác nhau ở hai dịp.',
      d:'Đúng. Phân khúc theo dịp chia các lần mua, không chia con người.'} },
  { type:'mcq', stem:'Tiệm muốn kiểm tra giả thuyết "đơn hộp lớn chủ yếu do doanh nghiệp đặt". Cách nhanh và rẻ nhất?',
    options:[{k:'a',t:'Thuê khảo sát 1.000 người trên toàn quốc về thói quen biếu quà Trung thu'},{k:'b',t:'Xem lại đơn năm ngoái: số lượng mỗi đơn, có xuất hoá đơn không, ngày đặt'},
             {k:'c',t:'Hỏi ý kiến nhân viên bán hàng lâu năm'},{k:'d',t:'Chạy thử quảng cáo nhắm "chủ doanh nghiệp" trên Facebook'}],
    answer:'b', why:{a:'Tốn kém và chậm, trong khi dữ liệu đơn hàng đã có sẵn.',
      b:'Đúng. Đơn nhiều hộp, có hoá đơn công ty, đặt sớm là dấu vết rõ của dịp biếu doanh nghiệp.',
      c:'Có ích để gợi ý, nhưng cảm nhận dễ lệch; dữ liệu đơn chắc hơn.',
      d:'Quảng cáo đo phản hồi quảng cáo, không trả lời ai đã mua hộp lớn.'} }
  ] },

/* ------------------------------------------------------------------ 03 */
{ id:'B:kh01-03', skill:'measure', read:'7 phút', t:'Khách mua thường xuyên và khách mua một lần: chia thế nào để tiêu tiền đúng?',
  situation:'Một shop mỹ phẩm online có 10.000 khách trong năm. Chủ shop định gửi mã giảm 20% cho tất cả. Bạn xem dữ liệu: 1.500 khách mua từ 4 lần trở lên, chiếm 55% doanh thu; 6.000 khách chỉ mua một lần; số còn lại mua 2–3 lần. Gửi chung một mã cho cả ba nhóm có phải là cách dùng tiền tốt?',
  concept:{ name:'Phân khúc theo hành vi',
    body:'Phân khúc theo hành vi chia khách theo <b>những gì họ đã làm</b>: mua bao lâu một lần, mua bao nhiêu, mua gần nhất khi nào, dùng kênh nào, phản ứng với khuyến mãi ra sao. Ưu điểm lớn: dữ liệu có sẵn trong hệ thống bán hàng và nói thật hơn lời khai. Mỗi nhóm hành vi cần một việc khác: nhóm mua đều cần được giữ và cảm ơn, nhóm mua một lần cần lý do để quay lại, nhóm lâu không mua cần được đánh thức. Một mã giảm chung thường tặng tiền cho người đằng nào cũng mua.' },
  example:'Nhóm 1.500 khách trung thành đằng nào cũng mua lại; giảm 20% cho họ chủ yếu là mất lãi. Nhóm 6.000 khách mua một lần mới là nơi mã giảm có tác dụng: kéo lần mua thứ hai. Shop đổi kế hoạch: nhóm trung thành nhận quà nhỏ và quyền mua sớm hàng mới; nhóm một lần nhận mã 15% hết hạn sau 14 ngày; nhóm 2–3 lần nhận gợi ý sản phẩm theo món đã mua.',
  takeaway:'Dữ liệu mua hàng là phân khúc có sẵn — mỗi nhóm hành vi cần một việc khác.',
  apply:'Mở danh sách đơn của một shop quen (hoặc tưởng tượng). Chia khách thành ba nhóm theo số lần mua và nói mỗi nhóm nên nhận gì, trong 60 giây.',
  mistakes:['Gửi cùng một mã giảm cho mọi khách, kể cả người đằng nào cũng mua.','Chỉ nhìn tổng doanh thu mà không tách ai mang lại doanh thu đó.'],
  q:[
  { type:'mcq', stem:'Đoán trước: gửi mã giảm 20% cho cả 10.000 khách thì phần tiền giảm nào ít hiệu quả nhất?',
    options:[{k:'a',t:'Phần gửi cho nhóm mua một lần vì họ khó quay lại'},{k:'b',t:'Phần gửi cho nhóm mua 2–3 lần vì họ còn đang phân vân giữa nhiều shop khác'},
             {k:'c',t:'Phần gửi cho nhóm trung thành vì họ đằng nào cũng mua'},{k:'d',t:'Phần gửi cho khách ở tỉnh vì phí ship đã cao'}],
    answer:'c', why:{a:'Nhóm một lần chính là nơi mã giảm có thể tạo thêm lần mua.',
      b:'Nhóm này còn dao động, mã giảm hay gợi ý có thể giúp họ gắn bó hơn.',
      c:'Đúng. Giảm giá cho người vốn sẽ mua là cho đi lãi mà không tạo thêm đơn.',
      d:'Nơi ở không phải là biến trong dữ liệu đang xét.'} },
  { type:'mcq', stem:'Bạn chọn làm gì với nhóm 1.500 khách mua từ 4 lần trở lên?',
    options:[{k:'a',t:'Tặng quà nhỏ, cho mua sớm hàng mới, hỏi ý kiến sản phẩm'},{k:'b',t:'Giảm 30% để thưởng lòng trung thành, mạnh tay hơn mức các nhóm khác'},
             {k:'c',t:'Không làm gì vì họ đã trung thành, dồn hết ngân sách cho khách mới'},{k:'d',t:'Gửi tin nhắn quảng cáo mỗi ngày để họ mua nhiều hơn'}],
    answer:'a', why:{a:'Đúng. Ghi nhận bằng đặc quyền giữ họ gắn bó mà không đốt lãi.',
      b:'Giảm sâu cho nhóm tạo 55% doanh thu là cắt vào phần lãi lớn nhất.',
      c:'Bỏ mặc nhóm quý nhất là mời đối thủ tới lấy.',
      d:'Nhắn dồn dập làm phiền, dễ khiến họ huỷ theo dõi.'} },
  { type:'calc', stem:'Doanh thu năm của shop là 4 tỉ đồng; nhóm 1.500 khách trung thành chiếm 55%. Doanh thu trung bình mỗi khách trung thành là bao nhiêu triệu đồng?',
    unit:'triệu đồng', ans:1.467, tol:0.01, wrong:[[0.22,'SAI_MAU_SO'],[2.667,'SAI_TINH_TOAN']], errors:['SAI_MAU_SO','SAI_TINH_TOAN'],
    steps:['Doanh thu nhóm = 4.000 triệu × 55% = 2.200 triệu.','Mỗi khách = 2.200 ÷ 1.500 ≈ <b>1,467 triệu đồng</b>.'] },
  { type:'mcq', stem:'Vì sao phân khúc theo hành vi thường đáng tin hơn khảo sát "bạn có trung thành với shop không"?',
    options:[{k:'a',t:'Vì khách hàng luôn nói dối trong mọi khảo sát trực tuyến'},{k:'b',t:'Vì dữ liệu hành vi ghi lại việc đã làm, không phụ thuộc trí nhớ hay thiện chí'},
             {k:'c',t:'Vì khảo sát bị cấm theo quy định mới về dữ liệu cá nhân ở Việt Nam'},{k:'d',t:'Vì dữ liệu hành vi rẻ hơn'}],
    answer:'b', why:{a:'Khách không luôn nói dối; họ hay nhớ sai hoặc trả lời theo điều nên làm.',
      b:'Đúng. Lịch sử mua là sự thật đã xảy ra, ít bị méo bởi cách hỏi.',
      c:'Khảo sát vẫn hợp pháp nếu làm đúng quy định; đó không phải lý do.',
      d:'Rẻ là lợi thế phụ, không phải lý do nó đáng tin hơn.'} },
  { type:'mcq', stem:'Tình huống mới: một ứng dụng giao đồ ăn thấy 30% người dùng chỉ đặt khi có mã freeship. Cách xử lý nhóm này hợp lý nhất?',
    options:[{k:'a',t:'Cho họ freeship mọi đơn để giữ chân bằng mọi giá'},{k:'b',t:'Chặn hẳn nhóm này khỏi mọi chương trình khuyến mãi của ứng dụng'},
             {k:'c',t:'Tính riêng lãi của nhóm; chỉ tặng mã khi đơn đủ lớn để vẫn có lãi'},{k:'d',t:'Gộp họ với nhóm trung thành vì họ đặt khá đều'}],
    answer:'c', why:{a:'Freeship mọi đơn có thể biến cả nhóm thành lỗ.',
      b:'Chặn hết thì mất cả phần đơn có lãi mà nhóm này vẫn mang lại.',
      c:'Đúng. Nhóm săn khuyến mãi cần luật riêng dựa trên lãi, không cần bị bỏ hay chiều chuộng.',
      d:'Đặt đều nhưng chỉ khi có mã là hành vi khác hẳn trung thành thật.'} },
  { type:'mcq', stem:'Nhóm 6.000 khách mua một lần. Chỉ số nào cho biết mã giảm 15% với họ có hiệu quả?',
    options:[{k:'a',t:'Số lượt mở email chứa mã giảm'},{k:'b',t:'Tổng doanh thu của cả shop trong tháng gửi mã, so với cùng tháng của năm trước'},
             {k:'c',t:'Số người theo dõi fanpage tăng thêm trong tháng'},{k:'d',t:'Tỉ lệ khách nhóm này mua lần hai so với nhóm không nhận mã'}],
    answer:'d', why:{a:'Mở email chưa phải mua lại.',
      b:'Tổng doanh thu lẫn nhiều yếu tố khác, không tách được tác dụng của mã.',
      c:'Theo dõi fanpage không liên quan trực tiếp tới mục tiêu mua lần hai.',
      d:'Đúng. So với nhóm đối chứng mới biết mã tạo thêm bao nhiêu lần mua thật.'} },
  { type:'mcq', stem:'Rủi ro khi chỉ phân khúc theo hành vi mà không tìm hiểu nhu cầu là gì?',
    options:[{k:'a',t:'Biết ai mua ít nhưng không biết vì sao, nên khó sửa đúng chỗ'},{k:'b',t:'Dữ liệu hành vi thường sai hoàn toàn nên không nên tin'},
             {k:'c',t:'Hệ thống bán hàng không lưu được số lần mua của khách'},{k:'d',t:'Khách sẽ phát hiện mình bị chia nhóm và phản đối shop trên mạng xã hội'}],
    answer:'a', why:{a:'Đúng. Hành vi cho biết "cái gì", nhu cầu cho biết "vì sao" — cần cả hai để quyết định sản phẩm và thông điệp.',
      b:'Dữ liệu hành vi thường chính xác; vấn đề là nó không giải thích.',
      c:'Hầu hết hệ thống bán hàng đều lưu lịch sử đơn.',
      d:'Chia nhóm để phục vụ khác nhau là việc bình thường, khách hiếm khi phản đối.'} }
  ] },

/* ------------------------------------------------------------------ 04 */
{ id:'B:kh01-04', skill:'insight', read:'6 phút', t:'Khách mua xe máy: người cần "bền, tiết kiệm" và người cần "đẹp, được khen" có chung một quảng cáo?',
  situation:'Một đại lý xe máy ở Cần Thơ bán hai dòng xe tay ga cùng tầm giá 35–45 triệu. Nhân viên kể có hai kiểu khách: một kiểu hỏi ngay "đổ đầy bình đi được bao xa, thay nhớt bao lâu", kiểu kia đứng soi màu, hỏi "đi ra đường có ai đụng hàng không". Đại lý đang dùng một tờ rơi liệt kê mọi thông số cho cả hai kiểu.',
  concept:{ name:'Phân khúc theo giá trị tìm kiếm (benefit)',
    body:'Phân khúc theo giá trị chia khách theo <b>lợi ích họ đặt lên hàng đầu</b> khi chọn: tiết kiệm, bền, an toàn, đẹp, thể hiện bản thân, tiện lợi. Cùng một sản phẩm, người này mua vì lý do lý trí, người kia vì cảm xúc. Chia theo giá trị giúp chọn điều gì nói trước tiên, hình ảnh nào, lời chứng thực từ ai. Nó khác bài phân khúc theo dịp: dịp là <b>khi nào</b> mua, còn giá trị là <b>vì điều gì</b> mà chọn cái này thay vì cái kia.' },
  example:'Đại lý tách tờ rơi thành hai: bản "chạy bền" nói 50 km/lít, bảo dưỡng mỗi 4.000 km, bảo hành 3 năm, kèm lời một anh giao hàng đã chạy 60.000 km; bản "phong cách" dùng ảnh xe màu độc quyền, gợi ý phụ kiện, kèm ảnh khách trẻ chụp check-in. Nhân viên hỏi một câu mở đầu — "anh chị ưu tiên điều gì nhất?" — rồi đưa đúng tờ.',
  takeaway:'Nói điều khách đặt lên hàng đầu trước — không phải mọi điều sản phẩm có.',
  apply:'Chọn một điện thoại phổ biến. Nêu hai nhóm khách tìm hai giá trị khác nhau ở cùng chiếc máy và câu mở đầu cho mỗi nhóm, trong 60 giây.',
  mistakes:['Liệt kê mọi ưu điểm cho mọi khách, ai cũng thấy nhạt.','Đoán giá trị khách tìm dựa vào ngoại hình hay tuổi thay vì hỏi.'],
  q:[
  { type:'mcq', stem:'Đoán trước: tờ rơi liệt kê mọi thông số cho cả hai kiểu khách gặp vấn đề gì?',
    options:[{k:'a',t:'Tờ rơi quá dài nên tốn chi phí in ấn cho đại lý'},{k:'b',t:'Mỗi kiểu khách phải tự lọc điều mình quan tâm giữa một rừng thông tin'},
             {k:'c',t:'Khách không tin thông số kỹ thuật do đại lý tự in ra, chỉ tin những gì hãng xe công bố'},{k:'d',t:'Tờ rơi không có giá bán nên khách không quyết được'}],
    answer:'b', why:{a:'Chi phí in là chuyện nhỏ so với việc thông điệp bị loãng.',
      b:'Đúng. Điều khách quan tâm nhất bị chìm giữa những điều họ không quan tâm.',
      c:'Không có dữ kiện về lòng tin; vấn đề là thứ tự ưu tiên.',
      d:'Giá có thể thiếu nhưng không giải thích được việc hai kiểu khách phản ứng khác nhau.'} },
  { type:'mcq', stem:'Bạn chọn làm gì để nhân viên phục vụ đúng hai nhóm?',
    options:[{k:'a',t:'Đoán theo tuổi: khách trên 35 nói tiết kiệm, dưới 35 nói kiểu dáng'},{k:'b',t:'In tờ rơi dày hơn với cả hai phần để khách tự chọn đọc'},
             {k:'c',t:'Hỏi một câu mở đầu về ưu tiên, rồi đưa tài liệu và lời kể phù hợp'},{k:'d',t:'Giảm giá cho nhóm quan tâm tiết kiệm để chốt nhanh hơn'}],
    answer:'c', why:{a:'Người 50 tuổi vẫn có thể mua vì đẹp; đoán theo tuổi dễ nhầm.',
      b:'Dày hơn chỉ làm rối hơn.',
      c:'Đúng. Một câu hỏi rẻ và chính xác hơn mọi phỏng đoán.',
      d:'Tiết kiệm là về chi phí sử dụng, không nhất thiết là muốn giảm giá mua.'} },
  { type:'mcq', stem:'Phân khúc theo giá trị khác phân khúc theo dịp ở chỗ nào?',
    options:[{k:'a',t:'Giá trị là "vì điều gì mà chọn", dịp là "mua khi nào, cho ai"'},{k:'b',t:'Giá trị chỉ dùng được cho hàng xa xỉ đắt tiền, còn dịp dùng cho hàng tiêu dùng nhanh giá rẻ'},
             {k:'c',t:'Giá trị dựa trên thu nhập, dịp dựa trên tuổi'},{k:'d',t:'Hai cách hoàn toàn giống nhau, chỉ khác tên gọi'}],
    answer:'a', why:{a:'Đúng. Hai câu hỏi khác nhau, và có thể dùng kết hợp.',
      b:'Cả hai đều dùng được ở mọi mức giá.',
      c:'Cả hai đều không dựa trên nhân khẩu học.',
      d:'Cùng một dịp (mua xe đi làm) vẫn có người tìm bền, người tìm đẹp.'} },
  { type:'mcq', stem:'Tình huống mới: một hãng nước mắm thấy khách chia hai nhóm — "độ đạm cao, nguyên chất" và "vị vừa, giá hợp lý, nấu hằng ngày". Nên làm gì với bao bì?',
    options:[{k:'a',t:'Một bao bì ghi đủ độ đạm, giá, vị, xuất xứ bằng cỡ chữ như nhau'},{k:'b',t:'Chỉ in độ đạm vì đó là thông số kỹ thuật quan trọng nhất của mọi loại nước mắm'},
             {k:'c',t:'Bỏ nhóm nấu hằng ngày vì nhóm này ít trung thành với thương hiệu'},{k:'d',t:'Hai dòng: một dòng đề cao độ đạm, một dòng đề cao vị vừa và giá'}],
    answer:'d', why:{a:'Mọi thứ bằng nhau thì không thứ gì nổi bật với nhóm nào.',
      b:'Nhóm nấu hằng ngày không chọn theo độ đạm; nói thế là nói sai người.',
      c:'Nhóm này thường là phần lớn lượng bán; bỏ là mất nền doanh thu.',
      d:'Đúng. Mỗi dòng hàng dẫn đầu bằng giá trị nhóm đó đặt lên đầu.'} },
  { type:'calc', stem:'Trong 200 khách hỏi xe tháng trước, 120 người hỏi về tiết kiệm xăng trước tiên. Nhóm "tìm sự tiết kiệm" chiếm bao nhiêu phần trăm?',
    unit:'%', ans:60, tol:0.1, wrong:[[40,'NHAM_TI_LE_ROI'],[166.7,'SAI_MAU_SO']], errors:['NHAM_TI_LE_ROI','SAI_MAU_SO'],
    steps:['Tỉ lệ = số khách nhóm ÷ tổng khách hỏi.','120 ÷ 200 = <b>60%</b>.'] },
  { type:'mcq', stem:'Làm sao biết khách thực sự đặt giá trị nào lên đầu, thay vì trả lời cho có?',
    options:[{k:'a',t:'Hỏi "anh chị có quan tâm tiết kiệm không" — ai cũng sẽ gật'},{k:'b',t:'Cho chọn một điều nếu chỉ được giữ một, hoặc xem họ hỏi gì đầu tiên'},
             {k:'c',t:'Chấm điểm từ 1 đến 5 cho từng lợi ích trên phiếu dài mười câu hỏi'},{k:'d',t:'Dựa vào loại xe họ đang đi'}],
    answer:'b', why:{a:'Câu hỏi có/không về điều tốt thì ai cũng gật; không phân biệt được ai.',
      b:'Đúng. Buộc đánh đổi hoặc quan sát câu hỏi đầu tiên lộ ra ưu tiên thật.',
      c:'Chấm điểm riêng từng mục thì mọi thứ đều được 4–5; không lộ ưu tiên.',
      d:'Xe đang đi có thể do người khác mua; không chắc phản ánh giá trị họ tìm.'} },
  { type:'mcq', stem:'Lời chứng thực nào hợp với nhóm "tìm sự bền bỉ"?',
    options:[{k:'a',t:'Một người nổi tiếng trẻ chụp ảnh cùng xe màu mới trong một buổi ra mắt'},{k:'b',t:'Một bảng xếp hạng lượt thích trên mạng xã hội của mẫu xe'},
             {k:'c',t:'Một anh giao hàng kể đã chạy 60.000 km chỉ thay nhớt'},{k:'d',t:'Một đoạn quảng cáo quay ở Hàn Quốc với nhạc sôi động và nhiều hiệu ứng'}],
    answer:'c', why:{a:'Hợp với nhóm phong cách, không phải nhóm cần bền.',
      b:'Lượt thích nói về độ nổi, không nói về độ bền.',
      c:'Đúng. Người chạy nhiều nhất là bằng chứng mạnh nhất cho độ bền.',
      d:'Hiệu ứng hình ảnh không trả lời câu hỏi "có bền không".'} }
  ] },

/* ------------------------------------------------------------------ 05 */
{ id:'B:kh01-05', skill:'measure', read:'7 phút', t:'Phân khúc nghe hay nhưng có dùng được không?',
  situation:'Nhóm bạn đề xuất một phân khúc cho thương hiệu trà túi lọc: "người trẻ thành thị yêu thiên nhiên, sống chậm, thích thiền buổi sáng". Cả phòng thích vì nghe đẹp. Trưởng nhóm hỏi ba câu: nhóm này có bao nhiêu người, họ có mua khác người khác không, và mình tìm họ ở đâu? Không ai trả lời được.',
  concept:{ name:'Bốn phép thử một phân khúc dùng được',
    body:'Một phân khúc chỉ đáng theo đuổi khi qua bốn phép thử. <b>Đủ lớn</b>: đủ người để bù chi phí làm riêng. <b>Khác biệt</b>: nhóm này phản ứng khác nhóm khác với sản phẩm, giá hay thông điệp. <b>Tiếp cận được</b>: có kênh, điểm bán hay nền tảng để nói với họ mà không tốn phí cho người ngoài nhóm. <b>Đo được</b>: có cách đếm hay ước lượng quy mô và theo dõi kết quả. Phân khúc nghe đẹp nhưng trượt một phép thử thì chỉ là một câu chuyện hay trong buổi họp.' },
  example:'Nhóm viết lại: "người mua trà túi lọc để uống thay cà phê buổi chiều ở văn phòng". Đủ lớn: ước lượng từ số nhân viên văn phòng ở hai thành phố lớn. Khác biệt: họ cần ít caffeine, pha nhanh, hộp để bàn — khác người mua trà biếu. Tiếp cận được: qua sàn thương mại điện tử giao văn phòng và bán sỉ cho phòng hành chính công ty. Đo được: theo dõi đơn hộp 50 gói giao giờ hành chính.',
  takeaway:'Đủ lớn, khác biệt, tiếp cận được, đo được — trượt một là chưa dùng được.',
  apply:'Lấy một phân khúc bạn từng nghe trong buổi họp. Chạy qua bốn phép thử và nói nó trượt ở đâu, trong 60 giây.',
  mistakes:['Chọn phân khúc vì mô tả nghe hay, không vì nó qua được phép thử.','Tìm được nhóm rất rõ nét nhưng quá nhỏ để nuôi một dòng sản phẩm.'],
  q:[
  { type:'mcq', stem:'Đoán trước: phân khúc "người trẻ yêu thiên nhiên, sống chậm, thích thiền buổi sáng" trượt rõ nhất ở phép thử nào?',
    options:[{k:'a',t:'Khác biệt, vì ai cũng thích thiên nhiên cả'},{k:'b',t:'Tiếp cận và đo được: không biết tìm và đếm họ ở đâu'},
             {k:'c',t:'Đủ lớn, vì người thiền buổi sáng ở Việt Nam chắc chắn rất ít, không đáng để đầu tư'},{k:'d',t:'Không trượt phép thử nào vì mô tả đã rất rõ nét'}],
    answer:'b', why:{a:'Có thể có phần đúng, nhưng vấn đề lộ rõ nhất trong buổi họp là không ai biết tìm họ ở đâu.',
      b:'Đúng. Mô tả toàn thái độ, không gắn với kênh hay dữ liệu nào để đếm và nói chuyện với họ.',
      c:'Chưa ai đo nên chưa biết lớn hay nhỏ; "chắc chắn ít" cũng là đoán.',
      d:'Rõ nét về cảm xúc không có nghĩa là dùng được trong thực tế.'} },
  { type:'mcq', stem:'Bạn sửa phân khúc đó thế nào để dùng được?',
    options:[{k:'a',t:'Thêm độ tuổi 22–30 và thu nhập trên 12 triệu cho rõ hơn'},{k:'b',t:'Giữ nguyên, chỉ cần làm nội dung thật đẹp là đúng người sẽ tự tìm đến thương hiệu'},
             {k:'c',t:'Gắn vào hành vi và dịp đo được: uống trà thay cà phê buổi chiều ở văn phòng'},{k:'d',t:'Mở rộng thành "mọi người yêu thiên nhiên"'}],
    answer:'c', why:{a:'Thêm nhân khẩu học giúp nhắm quảng cáo, nhưng vẫn không nói họ mua khác gì.',
      b:'Hy vọng người đúng tự tìm đến là bỏ qua phép thử tiếp cận.',
      c:'Đúng. Hành vi và dịp cụ thể thì đếm được, tìm được kênh, và biết họ cần gì khác.',
      d:'Rộng hơn thì càng mất tính khác biệt.'} },
  { type:'mcq', stem:'Phép thử "khác biệt" hỏi điều gì?',
    options:[{k:'a',t:'Nhóm này có tên gọi riêng, dễ nhớ trong nội bộ không'},{k:'b',t:'Nhóm này có khác các đối thủ đang nhắm tới không'},
             {k:'c',t:'Nhóm này có sống ở khu vực địa lý khác với các nhóm còn lại trong thị trường không'},{k:'d',t:'Nhóm này có phản ứng khác nhóm khác với sản phẩm, giá, thông điệp không'}],
    answer:'d', why:{a:'Tên gọi là chuyện trình bày, không phải phép thử.',
      b:'Khác đối thủ là câu hỏi định vị, không phải phép thử phân khúc.',
      c:'Địa lý có thể là một biến, nhưng khác nơi ở chưa chắc khác cách mua.',
      d:'Đúng. Nếu hai nhóm phản ứng giống nhau thì tách ra không đổi được quyết định nào.'} },
  { type:'calc', stem:'Ước lượng: hai thành phố có 1,2 triệu nhân viên văn phòng; 25% uống trà buổi chiều; một nửa trong số đó dùng trà túi lọc. Phân khúc có khoảng bao nhiêu nghìn người?',
    unit:'nghìn người', ans:150, tol:1, wrong:[[300,'QUEN_TI_LE_CHUYEN_DOI'],[600,'SAI_TINH_TOAN']], errors:['QUEN_TI_LE_CHUYEN_DOI','SAI_TINH_TOAN'],
    steps:['1.200 nghìn × 25% = 300 nghìn người uống trà buổi chiều.','300 × 50% = <b>150 nghìn người</b> dùng trà túi lọc.'] },
  { type:'mcq', stem:'Tình huống mới: một phòng khám nha khoa định nhắm "người sợ đau khi chữa răng". Phép thử nào khó qua nhất và xử lý ra sao?',
    options:[{k:'a',t:'Đủ lớn: vì người sợ đau rất ít, nên bỏ ngay'},{k:'b',t:'Tiếp cận: tìm qua từ khoá lo lắng như "nhổ răng có đau không"'},
             {k:'c',t:'Khác biệt: vì mọi bệnh nhân đều có nhu cầu giống hệt nhau, nên chỉ cần quảng cáo chung chung'},{k:'d',t:'Đo được: không thể đếm nên bỏ phân khúc'}],
    answer:'b', why:{a:'Người sợ đau chữa răng thường khá đông; bỏ ngay là vội.',
      b:'Đúng. Nỗi sợ không ghi trên hồ sơ, nhưng lộ ra ở điều người ta tìm kiếm — đó là kênh tiếp cận.',
      c:'Người sợ đau cần lời hứa khác hẳn (gây tê, giải thích từng bước); nhóm này khác thật.',
      d:'Đếm được gián tiếp qua lượng tìm kiếm và câu hỏi lúc đặt lịch.'} },
  { type:'mcq', stem:'Một phân khúc qua cả bốn phép thử nhưng đối thủ lớn đã phục vụ rất tốt. Kết luận hợp lý?',
    options:[{k:'a',t:'Phân khúc vẫn dùng được; chọn có vào đó hay không là quyết định khác'},{k:'b',t:'Phân khúc sai, phải chia lại từ đầu vì đã có đối thủ'},
             {k:'c',t:'Phải vào ngay vì đã chứng minh được đó là thị trường thật'},{k:'d',t:'Bỏ hẳn toàn ngành hàng vì không thể cạnh tranh với doanh nghiệp đã lớn'}],
    answer:'a', why:{a:'Đúng. Phép thử nói phân khúc có thật; chọn phục vụ ai còn tuỳ sức cạnh tranh — đó là bước chọn tệp.',
      b:'Có đối thủ không làm phân khúc sai.',
      c:'Có thật chưa đủ để vào; còn phải xét mình có thắng được không.',
      d:'Vội vàng; có thể có phân khúc khác mà đối thủ bỏ trống.'} },
  { type:'mcq', stem:'Vì sao "đủ lớn" không có một con số chung cho mọi ngành?',
    options:[{k:'a',t:'Vì luật mỗi ngành quy định khác nhau'},{k:'b',t:'Vì nhóm dưới 10.000 người luôn là quá nhỏ với mọi ngành'},
             {k:'c',t:'Vì phải bù được chi phí làm riêng, mà chi phí này khác từng ngành'},{k:'d',t:'Vì chỉ có số liệu tuyệt đối mới có ý nghĩa, còn tỉ lệ thì không nói lên điều gì'}],
    answer:'c', why:{a:'Không có luật nào quy định quy mô phân khúc.',
      b:'Với nha khoa hay thiết bị công nghiệp, vài nghìn khách có thể là quá đủ.',
      c:'Đúng. Đủ lớn là so với chi phí và biên lãi: xe hơi cần ít khách hơn nhiều so với nước ngọt.',
      d:'Cả số tuyệt đối và tỉ lệ đều cần; vấn đề là so với chi phí.'} }
  ] },

/* ------------------------------------------------------------------ 06 */
{ id:'B:kh01-06', skill:'measure', read:'7 phút', t:'Phân khúc có bao nhiêu tiền? Ước lượng nhanh trước khi đầu tư',
  situation:'Một startup muốn ra dòng cơm hộp ăn kiêng giao tận văn phòng ở Hà Nội, giá 60.000đ/hộp. Nhà đầu tư hỏi: "phân khúc này đáng bao nhiêu tiền một năm?". Không có báo cáo ngành nào có sẵn con số. Bạn có một buổi chiều để đưa ra ước lượng có căn cứ.',
  concept:{ name:'Ước lượng quy mô từ dưới lên',
    body:'Khi không có số liệu sẵn, hãy dựng quy mô <b>từ dưới lên</b>: bắt đầu từ tổng số người có thể liên quan, nhân dần với các tỉ lệ lọc (có nhu cầu, có khả năng chi, có dịp mua), rồi nhân tần suất mua và giá. Mỗi tỉ lệ phải có nguồn: số liệu công khai, khảo sát nhỏ, hay đếm thử. Kết quả không cần chính xác đến đồng; cần <b>đúng bậc độ lớn</b> và cho thấy tỉ lệ nào mình chắc, tỉ lệ nào đang đoán. Ghi rõ giả định để người khác thử thay số.' },
  example:'Giả định: 800.000 nhân viên văn phòng ở các quận trung tâm; 20% đang cố ăn kiêng hoặc giảm cân; một nửa trong đó sẵn sàng trả 60.000đ cho bữa trưa → 80.000 người. Mỗi người đặt trung bình 2 bữa/tuần, 48 tuần/năm → 96 bữa. Quy mô ≈ 80.000 × 96 × 60.000đ ≈ 460 tỉ đồng/năm. Tỉ lệ 20% là tỉ lệ yếu nhất, nên nhóm khảo sát 200 người ở ba toà văn phòng trước khi gọi vốn.',
  takeaway:'Nhân từng lớp lọc có nguồn — và nói rõ con số nào đang đoán.',
  apply:'Ước lượng số ly trà sữa bán mỗi ngày ở quận bạn sống, nói to từng giả định trong 60 giây.',
  mistakes:['Lấy dân số cả nước nhân 1% rồi gọi là quy mô thị trường.','Quên nhân tần suất mua, tính như mỗi người chỉ mua một lần.'],
  q:[
  { type:'mcq', stem:'Đoán trước: cách ước lượng nào dễ sai nhất?',
    options:[{k:'a',t:'Lấy 100 triệu dân nhân "chỉ cần 1% mua" là có quy mô'},{k:'b',t:'Đếm số toà văn phòng trong quận rồi nhân số người trung bình'},
             {k:'c',t:'Khảo sát nhỏ 200 người văn phòng để lấy tỉ lệ ăn kiêng'},{k:'d',t:'Xem số đơn cơm trưa của một quán gần các toà nhà rồi suy rộng ra theo mật độ'}],
    answer:'a', why:{a:'Đúng. "1% của cả nước" không có căn cứ nào; nó bỏ qua ai thực sự có nhu cầu và có thể mua.',
      b:'Đếm từ dưới lên là cách làm tốt.',
      c:'Khảo sát nhỏ có sai số, nhưng cho một tỉ lệ có nguồn.',
      d:'Dữ liệu thật từ điểm bán là căn cứ tốt để kiểm tra chéo.'} },
  { type:'mcq', stem:'Nhà đầu tư nghi ngờ con số. Bạn chọn làm gì trước?',
    options:[{k:'a',t:'Tăng tỉ lệ ăn kiêng lên 30% cho con số ấn tượng hơn'},{k:'b',t:'Tìm thêm một báo cáo ngành nước ngoài để trích dẫn cho có vẻ chuyên nghiệp'},
             {k:'c',t:'Giữ nguyên và nói con số này đã được tính rất kỹ'},{k:'d',t:'Chỉ ra giả định yếu nhất (20%) và kế hoạch kiểm tra nó bằng khảo sát'}],
    answer:'d', why:{a:'Đẩy số lên để đẹp làm mất lòng tin ngay khi bị hỏi lại.',
      b:'Báo cáo nước ngoài không phản ánh văn phòng Hà Nội.',
      c:'Khẳng định mà không mở giả định thì không thuyết phục ai.',
      d:'Đúng. Minh bạch giả định yếu nhất và cách kiểm tra là cách xây lòng tin.'} },
  { type:'calc', stem:'Theo ví dụ: 80.000 người, mỗi người 96 bữa/năm, giá 60.000đ. Quy mô phân khúc là bao nhiêu tỉ đồng/năm? (làm tròn một chữ số thập phân)',
    unit:'tỉ đồng', ans:460.8, tol:0.5, wrong:[[4.8,'NGUOC_TAN_SUAT'],[9.6,'SAI_TINH_TOAN']], errors:['NGUOC_TAN_SUAT','SAI_TINH_TOAN'],
    steps:['Số bữa/năm = 80.000 × 96 = 7.680.000 bữa.','Doanh thu = 7.680.000 × 60.000đ = 460.800.000.000đ ≈ <b>460,8 tỉ đồng</b>.'] },
  { type:'mcq', stem:'Nếu tần suất thật chỉ là 1 bữa/tuần thay vì 2, quy mô thay đổi thế nào?',
    options:[{k:'a',t:'Giảm khoảng 10% vì tần suất chỉ là một yếu tố nhỏ'},{k:'b',t:'Giảm một nửa, vì quy mô tỉ lệ thuận với tần suất'},
             {k:'c',t:'Không đổi vì số người trong phân khúc vẫn giữ nguyên như trước'},{k:'d',t:'Tăng lên vì mỗi bữa sẽ được đặt nhiều món hơn'}],
    answer:'b', why:{a:'Tần suất nhân trực tiếp vào kết quả; giảm một nửa thì kết quả giảm một nửa.',
      b:'Đúng. Mọi yếu tố trong phép nhân đều tác động theo tỉ lệ.',
      c:'Số người giữ nguyên nhưng số bữa giảm, nên doanh thu giảm.',
      d:'Không có dữ kiện nào nói mỗi bữa có thêm món.'} },
  { type:'mcq', stem:'Tình huống mới: một shop đồ chơi gỗ muốn ước lượng phân khúc "phụ huynh mua đồ chơi giáo dục cho con 2–5 tuổi" ở TP.HCM. Lớp lọc đầu tiên nên là gì?',
    options:[{k:'a',t:'Số trẻ 2–5 tuổi ở TP.HCM từ số liệu dân số công khai'},{k:'b',t:'Số người theo dõi các trang Facebook về nuôi dạy con cái ở cả nước'},
             {k:'c',t:'Tổng doanh thu ngành đồ chơi Việt Nam'},{k:'d',t:'Số lượt tìm kiếm "đồ chơi" trên Google trong năm, gồm cả đồ chơi điện tử'}],
    answer:'a', why:{a:'Đúng. Bắt đầu từ đơn vị gốc có số liệu tin được, rồi lọc dần theo nhu cầu và khả năng chi.',
      b:'Người theo dõi trang không phải là số trẻ; lẫn cả người ngoài TP.HCM.',
      c:'Đó là cách từ trên xuống, và lẫn mọi loại đồ chơi.',
      d:'Lượt tìm kiếm lẫn quá nhiều nhu cầu khác nhau.'} },
  { type:'mcq', stem:'Nên dùng ước lượng từ trên xuống (lấy báo cáo ngành rồi chia nhỏ) khi nào?',
    options:[{k:'a',t:'Không bao giờ, vì báo cáo ngành luôn sai số rất lớn'},{k:'b',t:'Luôn luôn, vì nó nhanh và trông chuyên nghiệp hơn trong buổi thuyết trình'},
             {k:'c',t:'Để kiểm tra chéo: nếu hai cách lệch nhau quá xa, có giả định sai'},{k:'d',t:'Chỉ khi phân khúc là hàng xa xỉ'}],
    answer:'c', why:{a:'Báo cáo ngành có ích để so sánh, dù không đủ chi tiết.',
      b:'Từ trên xuống dễ che các giả định; dùng một mình thì yếu.',
      c:'Đúng. Hai cách gặp nhau ở cùng bậc độ lớn thì đáng tin hơn nhiều.',
      d:'Loại hàng không quyết định việc kiểm tra chéo.'} },
  { type:'mcq', stem:'Quy mô phân khúc 460 tỉ đồng/năm có nghĩa là startup sẽ có doanh thu đó?',
    options:[{k:'a',t:'Có, nếu làm marketing đủ mạnh trong năm đầu tiên'},{k:'b',t:'Có, vì ước lượng từ dưới lên đã tính đúng người mua thật'},
             {k:'c',t:'Có, sau khoảng ba năm nếu tăng trưởng đều'},{k:'d',t:'Không; đó là trần của cả phân khúc, startup chỉ lấy được một phần'}],
    answer:'d', why:{a:'Marketing mạnh không thể lấy hết phân khúc; còn đối thủ và các lựa chọn khác.',
      b:'Người có nhu cầu chưa phải khách của mình.',
      c:'Không có căn cứ cho mốc ba năm.',
      d:'Đúng. Quy mô là cái bánh; phần của mình phụ thuộc năng lực phân phối và cạnh tranh.'} }
  ] },

/* ------------------------------------------------------------------ 07 */
{ id:'B:kh01-07', skill:'brand', read:'7 phút', t:'Một sản phẩm, ba phân khúc: làm riêng hay làm chung?',
  situation:'Một thương hiệu bánh mì sandwich đóng gói bán ở cửa hàng tiện lợi. Dữ liệu cho thấy ba nhóm: học sinh mua ăn sáng vội (bánh 10.000đ), nhân viên mua ăn trưa nhẹ (cần no, ít béo) và người đi phượt mua mang theo (cần để được lâu). Ngân sách chỉ đủ một chiến dịch lớn trong năm. Làm ba bản riêng hay một bản chung?',
  concept:{ name:'Phục vụ nhiều phân khúc bằng một sản phẩm',
    body:'Không phải mỗi phân khúc đều cần một sản phẩm riêng. Có ba cách: <b>chung lõi, khác bề mặt</b> — một sản phẩm, đổi quy cách, kênh và thông điệp theo nhóm; <b>chung thông điệp gốc</b> — tìm lợi ích mà mọi nhóm đều cần rồi nói điều đó; <b>tách dòng</b> — làm biến thể riêng khi nhu cầu khác đến mức một sản phẩm không vừa. Chọn dựa trên chi phí làm riêng so với phần doanh số tăng thêm, và nguy cơ thông điệp chung bị nhạt.' },
  example:'Thương hiệu chọn chung lõi, khác bề mặt: giữ một công thức bánh, làm gói đôi cho người phượt (in hạn dùng rõ), gói đơn giá 10.000đ cho học sinh đặt gần quầy thu ngân buổi sáng, và combo bánh + sữa cho bữa trưa văn phòng. Chiến dịch lớn nói lợi ích chung "no gọn trong một tay", mỗi điểm bán có biển nhỏ riêng cho dịp của mình. Chi phí thêm chỉ là bao bì và biển, không phải ba dây chuyền.',
  takeaway:'Tách bề mặt trước, tách sản phẩm chỉ khi một lõi không còn vừa.',
  apply:'Chọn một món hàng tiện lợi. Nói ba nhóm mua nó và cách đổi bề mặt (gói, kênh, lời nói) cho từng nhóm, trong 60 giây.',
  mistakes:['Làm sản phẩm riêng cho mỗi nhóm khi chỉ cần đổi gói và điểm đặt.','Viết một thông điệp chung chung đến mức không nhóm nào thấy mình trong đó.'],
  q:[
  { type:'mcq', stem:'Đoán trước: với ngân sách chỉ đủ một chiến dịch lớn, cách nào hợp lý nhất?',
    options:[{k:'a',t:'Ba chiến dịch nhỏ riêng, mỗi cái một phần ba ngân sách'},{k:'b',t:'Một chiến dịch chung nói lợi ích mọi nhóm cần, đổi bề mặt theo điểm bán'},
             {k:'c',t:'Chỉ nói với nhóm học sinh vì đông nhất'},{k:'d',t:'Làm ba công thức bánh khác nhau rồi mới quảng cáo cho từng nhóm bằng ba chiến dịch riêng'}],
    answer:'b', why:{a:'Chia ba thì mỗi chiến dịch quá mỏng để được nhớ.',
      b:'Đúng. Lõi chung giữ sức nặng, bề mặt riêng giữ độ đúng người.',
      c:'Có thể là lựa chọn, nhưng bỏ hai nhóm đang mua sẵn là phí khi đổi bề mặt rất rẻ.',
      d:'Tốn chi phí sản xuất lớn trước khi biết có cần hay không.'} },
  { type:'mcq', stem:'Nhóm người phượt phàn nàn bánh hỏng sau 2 ngày. Bạn chọn làm gì?',
    options:[{k:'a',t:'Đổi thông điệp quảng cáo cho nhóm phượt để họ ăn sớm hơn'},{k:'b',t:'Giảm giá gói đôi để bù chất lượng'},
             {k:'c',t:'Bỏ hẳn nhóm phượt khỏi kế hoạch vì họ quá khó tính'},{k:'d',t:'Cân nhắc tách dòng: biến thể bảo quản lâu hơn, nếu nhóm đủ lớn'}],
    answer:'d', why:{a:'Thông điệp không sửa được hạn dùng; đây là nhu cầu sản phẩm thật.',
      b:'Giảm giá không làm bánh để lâu hơn.',
      c:'Bỏ ngay là vội; cần xem quy mô trước.',
      d:'Đúng. Khi lõi không còn vừa nhu cầu, tách dòng — nhưng chỉ khi quy mô bù được chi phí.'} },
  { type:'calc', stem:'Làm dòng bánh để lâu tốn thêm 300 triệu đồng/năm. Mỗi gói lãi 4.000đ. Cần bán thêm tối thiểu bao nhiêu nghìn gói để bù chi phí?',
    unit:'nghìn gói', ans:75, tol:0.5, wrong:[[1.2,'SAI_TINH_TOAN'],[7.5,'SAI_TINH_TOAN']], errors:['SAI_TINH_TOAN'],
    steps:['Số gói hoà vốn = chi phí thêm ÷ lãi mỗi gói.','300.000.000 ÷ 4.000 = 75.000 gói = <b>75 nghìn gói</b>.'] },
  { type:'mcq', stem:'Rủi ro lớn nhất của một thông điệp chung cho cả ba nhóm là gì?',
    options:[{k:'a',t:'Nói điều chung chung đến mức không nhóm nào thấy mình trong đó'},{k:'b',t:'Chi phí sản xuất nội dung cao hơn làm riêng ba bản'},
             {k:'c',t:'Cửa hàng tiện lợi từ chối trưng bày sản phẩm có thông điệp chung'},{k:'d',t:'Các nhóm sẽ phát hiện ra họ nhận cùng thông điệp và thấy bị xem nhẹ'}],
    answer:'a', why:{a:'Đúng. Thông điệp chung phải là lợi ích thật sự chung, không phải câu vô thưởng vô phạt.',
      b:'Một bản thường rẻ hơn ba bản.',
      c:'Điểm bán không quan tâm thông điệp chung hay riêng.',
      d:'Khách hiếm khi để ý hay phản ứng chuyện này.'} },
  { type:'mcq', stem:'Tình huống mới: một hãng dầu gội bán cho cả nam và nữ, nhưng nhu cầu thật là "trị gàu" và "giữ màu tóc nhuộm". Nên tách theo gì?',
    options:[{k:'a',t:'Tách hai dòng nam và nữ với bao bì màu xanh và hồng'},{k:'b',t:'Một dòng chung cho mọi người, thông điệp nói về mùi thơm dễ chịu'},
             {k:'c',t:'Tách theo nhu cầu tóc: dòng trị gàu, dòng giữ màu — cho cả nam lẫn nữ'},{k:'d',t:'Tách theo tuổi: dưới 30 giữ màu, trên 30 trị gàu'}],
    answer:'c', why:{a:'Tách theo giới trong khi công thức cần khác nhau vì nhu cầu, không vì giới.',
      b:'Mùi thơm không giải quyết nhu cầu chính của nhóm nào.',
      c:'Đúng. Nhu cầu tóc quyết định công thức; giới tính chỉ ảnh hưởng bề mặt.',
      d:'Người trên 30 vẫn nhuộm tóc; tuổi không phải nguồn gốc nhu cầu.'} },
  { type:'mcq', stem:'Cách nào là "đổi bề mặt" chứ không phải "đổi lõi"?',
    options:[{k:'a',t:'Đổi công thức bánh sang ít béo cho nhóm văn phòng'},{k:'b',t:'Đặt bánh gần quầy thu ngân buổi sáng cho học sinh'},
             {k:'c',t:'Thay nguyên liệu để bánh để được 7 ngày ở nhiệt độ phòng'},{k:'d',t:'Làm bánh cỡ lớn gấp đôi cho người ăn nhiều, dùng khuôn mới'}],
    answer:'b', why:{a:'Đổi công thức là đổi lõi sản phẩm.',
      b:'Đúng. Vị trí đặt hàng là bề mặt: không đổi gì bên trong sản phẩm.',
      c:'Đổi nguyên liệu là đổi lõi.',
      d:'Khuôn mới, cỡ mới là thay đổi sản xuất.'} },
  { type:'mcq', stem:'Khi nào nên tách thành thương hiệu riêng thay vì chỉ tách dòng?',
    options:[{k:'a',t:'Khi hai phân khúc có giá trị mâu thuẫn, một tên làm hỏng cảm nhận của nhóm kia'},{k:'b',t:'Khi muốn tiết kiệm chi phí marketing'},
             {k:'c',t:'Khi có thêm một phân khúc mới bất kỳ xuất hiện trong dữ liệu bán hàng'},{k:'d',t:'Khi thương hiệu hiện tại đã quá nổi tiếng trên thị trường'}],
    answer:'a', why:{a:'Đúng. Bình dân và cao cấp chung một tên dễ kéo nhau xuống; lúc đó mới đáng tách tên.',
      b:'Thương hiệu riêng tốn kém hơn nhiều.',
      c:'Mỗi phân khúc mới không cần một thương hiệu.',
      d:'Nổi tiếng là tài sản để dùng, không phải lý do tách.'} }
  ] },

/* ------------------------------------------------------------------ 08 */
{ id:'B:kh01-08', skill:'comm', read:'6 phút', t:'Persona "Chị Hoa 32 tuổi thích đọc sách": giúp được gì hay chỉ để trang trí slide?',
  situation:'Agency gửi bộ persona cho thương hiệu máy lọc nước: "Chị Hoa, 32 tuổi, nhân viên ngân hàng, thích đọc sách, du lịch, uống cà phê, có hai con". Kèm ảnh stock một phụ nữ đang cười. Đội sản phẩm đọc xong vẫn không biết nên ưu tiên tính năng nào, đội nội dung không biết nên viết gì. Bộ persona sai ở đâu?',
  concept:{ name:'Persona có ích và persona vô dụng',
    body:'Persona là một nhân vật đại diện cho một phân khúc. Nó <b>vô dụng</b> khi chỉ gồm tuổi, nghề, sở thích chung chung — thông tin đúng với hàng triệu người và không gợi ra quyết định nào. Nó <b>có ích</b> khi trả lời: người này đang cố làm gì, điều gì làm họ lo, họ đang dùng giải pháp gì thay thế, điều gì khiến họ đổi, và họ tìm thông tin ở đâu. Mỗi dòng trong persona nên dẫn tới một quyết định; dòng nào không dẫn tới đâu thì bỏ.' },
  example:'Viết lại: "Chị Hoa đang đun nước sôi để nguội cho hai con vì không tin nước máy khu mình có mùi clo. Chị lo máy lọc thay lõi đắt và không biết lõi đã hết hạn chưa. Chị hỏi ý kiến trong nhóm Zalo phụ huynh của lớp. Chị sẽ đổi nếu có bằng chứng nước sạch và chi phí lõi dưới 100.000đ/tháng". Từ đây, đội sản phẩm ưu tiên đèn báo thay lõi; đội nội dung làm bảng chi phí mỗi tháng.',
  takeaway:'Persona tốt là persona khiến đội làm khác đi; không làm khác thì xoá bớt.',
  apply:'Viết lại một persona bạn từng thấy: bỏ sở thích, thêm nỗi lo, giải pháp đang dùng và điều khiến họ đổi — trong 60 giây.',
  mistakes:['Điền sở thích, cung hoàng đạo, ảnh stock cho sinh động mà không dùng tới.','Làm persona từ tưởng tượng của phòng họp thay vì từ lời khách thật.'],
  q:[
  { type:'mcq', stem:'Đoán trước: dòng nào trong persona ban đầu ít giúp quyết định nhất?',
    options:[{k:'a',t:'Có hai con nhỏ trong nhà'},{k:'b',t:'Là nhân viên ngân hàng, có thu nhập ổn định hằng tháng'},
             {k:'c',t:'Thích đọc sách, du lịch, uống cà phê'},{k:'d',t:'Sống ở thành phố lớn với nước máy có mùi'}],
    answer:'c', why:{a:'Có con nhỏ liên quan trực tiếp đến nỗi lo về nước sạch.',
      b:'Thu nhập có liên quan chút ít đến khả năng chi, dù chưa đủ.',
      c:'Đúng. Sở thích chung chung đúng với hàng triệu người và không nói gì về máy lọc nước.',
      d:'Chi tiết này thậm chí không có trong bản gốc, nhưng nếu có thì rất hữu ích.'} },
  { type:'mcq', stem:'Bạn được giao sửa persona trong một buổi. Bạn làm gì trước?',
    options:[{k:'a',t:'Tìm ảnh đẹp hơn và thêm cung hoàng đạo cho sinh động'},{k:'b',t:'Thêm hai persona mới để bao quát hết thị trường'},
             {k:'c',t:'Viết lại dựa trên đoán của cả phòng họp về khách hàng lý tưởng của thương hiệu'},{k:'d',t:'Gọi 5 khách thật hỏi họ lo gì, đang dùng gì, vì sao đổi'}],
    answer:'d', why:{a:'Trang trí thêm không làm persona dẫn tới quyết định nào.',
      b:'Nhiều persona rỗng hơn vẫn là rỗng.',
      c:'Đoán tập thể dễ ra chân dung mà cả phòng muốn, không phải khách thật.',
      d:'Đúng. Vài cuộc gọi thật cho ra nỗi lo và rào cản cụ thể mà không bàn họp nào có.'} },
  { type:'mcq', stem:'Dòng nào là dòng persona có ích?',
    options:[{k:'a',t:'Hiện đun nước sôi để nguội vì không tin nước máy'},{k:'b',t:'Năng động, yêu gia đình, hiện đại và luôn quan tâm tới sức khoẻ'},
             {k:'c',t:'32 tuổi, sống ở Hà Nội'},{k:'d',t:'Dùng iPhone và thích mua sắm trên các sàn thương mại điện tử lớn'}],
    answer:'a', why:{a:'Đúng. Giải pháp đang dùng là đối thủ thật và cho biết phải thắng cái gì.',
      b:'Tính từ chung chung ai cũng nhận; không gợi ra việc gì.',
      c:'Nhân khẩu học giúp nhắm, nhưng không nói gì về nhu cầu.',
      d:'Chi tiết thiết bị không liên quan tới quyết định mua máy lọc.'} },
  { type:'mcq', stem:'Tình huống mới: một app học tiếng Anh có persona "Minh, 20 tuổi, sinh viên, thích game và K-pop". Câu hỏi nào nên thêm vào để persona có ích?',
    options:[{k:'a',t:'Minh thích nhóm nhạc K-pop nào nhất và theo dõi bao lâu rồi'},{k:'b',t:'Minh chơi game gì, bao nhiêu giờ mỗi ngày'},
             {k:'c',t:'Minh học tiếng Anh để làm gì, đã bỏ app nào, vì sao bỏ'},{k:'d',t:'Minh sống ký túc xá hay ở nhà cùng bố mẹ'}],
    answer:'c', why:{a:'Có thể giúp chọn hình ảnh quảng cáo, nhưng không giúp thiết kế sản phẩm.',
      b:'Thói quen chơi game có thể gợi ý chút ít, nhưng không phải trọng tâm.',
      c:'Đúng. Mục tiêu học và lý do bỏ app cũ là nơi sản phẩm phải thắng.',
      d:'Nơi ở ít liên quan đến quyết định học.'} },
  { type:'mcq', stem:'Nên có bao nhiêu persona cho một thương hiệu?',
    options:[{k:'a',t:'Càng nhiều càng tốt để bao quát toàn bộ thị trường'},{k:'b',t:'Mỗi phân khúc đã chọn phục vụ một persona, thường 2–4'},
             {k:'c',t:'Luôn đúng một persona để đội tập trung'},{k:'d',t:'Bằng đúng số nhóm tuổi trong dữ liệu khách hàng hiện có của công ty'}],
    answer:'b', why:{a:'Mười persona thì không ai nhớ, và không ai dùng.',
      b:'Đúng. Persona đi theo phân khúc được chọn; ít và rõ thì đội mới dùng.',
      c:'Một persona có thể thiếu nếu thương hiệu phục vụ vài nhu cầu khác nhau.',
      d:'Chia theo tuổi là lặp lại đúng lỗi phân khúc nhân khẩu học.'} },
  { type:'mcq', stem:'Làm sao kiểm tra một persona có đang được dùng thật?',
    options:[{k:'a',t:'Xem nó có trong mọi bộ slide thuyết trình không'},{k:'b',t:'Hỏi agency đã làm persona xem họ có hài lòng với chất lượng của nó không'},
             {k:'c',t:'Đếm số trang của tài liệu persona'},{k:'d',t:'Xem các quyết định gần đây có viện dẫn nỗi lo hay rào cản trong nó'}],
    answer:'d', why:{a:'Có mặt trong slide không có nghĩa là được dùng để quyết định.',
      b:'Người làm hài lòng không chứng minh được người dùng cần nó.',
      c:'Dài hơn thường là tệ hơn.',
      d:'Đúng. Persona sống khi người ta trích nó để chọn tính năng hay viết nội dung.'} },
  { type:'calc', stem:'Chị Hoa chấp nhận chi phí lõi dưới 100.000đ/tháng. Bộ lõi giá 1.080.000đ, dùng được 12 tháng. Chi phí lõi mỗi tháng là bao nhiêu nghìn đồng?',
    unit:'nghìn đồng', ans:90, tol:0.5, wrong:[[1080,'NGUOC_TAN_SUAT'],[12960,'SAI_TINH_TOAN']], errors:['NGUOC_TAN_SUAT','SAI_TINH_TOAN'],
    steps:['Chi phí mỗi tháng = giá bộ lõi ÷ số tháng dùng.','1.080.000 ÷ 12 = 90.000đ = <b>90 nghìn đồng</b> — dưới ngưỡng 100.000đ.'] }
  ] },

/* ------------------------------------------------------------------ 09 */
{ id:'B:kh01-09', skill:'insight', read:'7 phút', t:'Dữ liệu nói "khách chủ yếu nữ 25–34" — có nên chỉ nhắm nhóm đó?',
  situation:'Một thương hiệu nến thơm bán online xem báo cáo: 70% người mua là nữ 25–34. Chủ thương hiệu định dồn toàn bộ quảng cáo vào nhóm này. Bạn đọc kỹ đơn hàng và thấy 30% đơn có ghi chú "gói quà", nhiều đơn giao đến địa chỉ khác người đặt, và có một nhóm nam đặt vào tuần trước 14/2 và 20/10.',
  concept:{ name:'Nhân khẩu học đánh lừa như thế nào',
    body:'Báo cáo nhân khẩu học mô tả <b>người đang mua</b>, không phải <b>người có thể mua</b> hay <b>lý do mua</b>. Nó đánh lừa theo ba cách. Thứ nhất, nó phản ánh chính nơi bạn đã quảng cáo — nhắm nữ thì khách ra nữ. Thứ hai, nó giấu các dịp mua khác nhau trong cùng một nhóm. Thứ ba, nó bỏ sót nhóm nhỏ nhưng có giá trị, như người mua quà. Đọc nhân khẩu học cùng với ghi chú đơn, dịp mua và địa chỉ nhận để thấy phân khúc thật.' },
  example:'Tách đơn theo dịp: đơn "tự dùng" chủ yếu nữ 25–34, giá trị trung bình 250.000đ. Đơn "quà tặng" — cả nam lẫn nữ — giá trị trung bình 420.000đ vì hay mua hộp quà và thêm thiệp. Nhóm nam chỉ chiếm 12% đơn nhưng tập trung vào ba dịp lễ. Thương hiệu giữ quảng cáo cho nữ, và thêm một đợt "quà tặng dễ chọn" chạy hai tuần trước mỗi dịp lễ, có gói sẵn và giao tận người nhận.',
  takeaway:'Báo cáo tuổi và giới cho biết ai đã mua — không cho biết ai sẽ mua và vì sao.',
  apply:'Mở báo cáo khách hàng của một trang bạn biết. Nêu một nhóm có thể bị che khuất sau con số nhân khẩu học lớn nhất, trong 60 giây.',
  mistakes:['Dồn hết ngân sách vào nhóm nhân khẩu học lớn nhất mà không hỏi vì sao họ lớn.','Bỏ qua nhóm nhỏ có giá trị đơn cao chỉ vì họ ít về số lượng.'],
  q:[
  { type:'mcq', stem:'Đoán trước: vì sao con số "70% là nữ 25–34" có thể đánh lừa?',
    options:[{k:'a',t:'Vì số liệu từ nền tảng quảng cáo luôn sai về giới tính và độ tuổi của người mua'},{k:'b',t:'Vì nữ 25–34 không thật sự thích nến thơm'},
             {k:'c',t:'Vì 70% là quá cao, số liệu thật thường dưới 50%'},{k:'d',t:'Vì nó có thể chỉ phản ánh nơi thương hiệu đã quảng cáo, và che các dịp mua khác'}],
    answer:'d', why:{a:'Số liệu có sai số, nhưng không phải luôn sai; vấn đề là cách đọc.',
      b:'Họ đang mua thật; vấn đề là họ không phải toàn bộ cơ hội.',
      c:'Không có ngưỡng nào như vậy.',
      d:'Đúng. Nhắm ai thì ra khách đó; và một nhóm nhân khẩu học có thể chứa nhiều dịp mua khác nhau.'} },
  { type:'mcq', stem:'Bạn đề xuất gì với kế hoạch dồn toàn bộ quảng cáo vào nữ 25–34?',
    options:[{k:'a',t:'Giữ phần chính cho nữ, thêm đợt "quà tặng" trước dịp lễ nhắm người mua quà'},{k:'b',t:'Đồng ý, vì dữ liệu đã cho thấy rõ ai là khách chính của thương hiệu'},
             {k:'c',t:'Chuyển hết sang nhắm nam vì đơn giá trị cao hơn'},{k:'d',t:'Tạm dừng quảng cáo để khảo sát toàn bộ khách trong ba tháng'}],
    answer:'a', why:{a:'Đúng. Giữ nền đang chạy tốt và mở thêm dịp quà tặng có giá trị đơn cao.',
      b:'Bỏ qua nhóm quà tặng đang lộ rõ trong ghi chú đơn.',
      c:'Nhóm nam chỉ 12% đơn và tập trung theo dịp lễ; chuyển hết là quá tay.',
      d:'Dừng ba tháng làm mất doanh thu trong khi dữ liệu đơn đã đủ để hành động.'} },
  { type:'calc', stem:'Tháng trước có 1.000 đơn: 700 đơn tự dùng, giá trị trung bình 250.000đ; 300 đơn quà tặng, trung bình 420.000đ. Nhóm quà tặng chiếm bao nhiêu phần trăm doanh thu? (làm tròn một chữ số thập phân)',
    unit:'%', ans:41.9, tol:0.2, wrong:[[30,'NHAM_SO_TUYET_DOI'],[72.0,'SAI_MAU_SO']], errors:['NHAM_SO_TUYET_DOI','SAI_MAU_SO'],
    steps:['Doanh thu tự dùng = 700 × 250.000 = 175 triệu; quà tặng = 300 × 420.000 = 126 triệu.','Tổng = 301 triệu; tỉ trọng quà tặng = 126 ÷ 301 ≈ <b>41,9%</b>.'] },
  { type:'mcq', stem:'Dấu vết nào trong dữ liệu đơn hàng cho biết có phân khúc "mua quà"?',
    options:[{k:'a',t:'Người mua dùng điện thoại để đặt hàng'},{k:'b',t:'Đơn có ghi chú gói quà và giao tới địa chỉ khác người đặt'},
             {k:'c',t:'Đơn thanh toán bằng ví điện tử thay vì tiền mặt khi nhận hàng tại nhà'},{k:'d',t:'Đơn đặt vào buổi tối'}],
    answer:'b', why:{a:'Hầu hết đơn đều đặt bằng điện thoại.',
      b:'Đúng. Gói quà và người nhận khác người đặt là dấu hiệu trực tiếp của dịp tặng.',
      c:'Phương thức thanh toán không liên quan đến dịp mua.',
      d:'Giờ đặt không phân biệt tự dùng với tặng.'} },
  { type:'mcq', stem:'Tình huống mới: một hãng sữa bột người lớn thấy 65% người mua là nữ 30–45. Điều gì dễ bị che khuất nhất?',
    options:[{k:'a',t:'Nữ 30–45 thật ra không uống sữa'},{k:'b',t:'Sữa bột người lớn không còn được ưa chuộng trên thị trường như những năm trước'},
             {k:'c',t:'Người uống thật là bố mẹ lớn tuổi; con gái mua hộ'},{k:'d',t:'Hãng đang bán giá quá cao so với đối thủ'}],
    answer:'c', why:{a:'Không có dữ kiện; và điều này không phải là thứ bị che.',
      b:'Không có dữ kiện về xu hướng thị trường.',
      c:'Đúng. Người mua và người dùng khác nhau: thông điệp phải nói với người mua về lợi ích cho người dùng.',
      d:'Giá không phải thứ con số nhân khẩu học che đi.'} },
  { type:'mcq', stem:'Vì sao nhóm nam 12% đơn vẫn đáng chú ý?',
    options:[{k:'a',t:'Vì nam giới luôn chi tiêu nhiều hơn nữ giới ở mọi ngành hàng'},{k:'b',t:'Vì cần đủ cả hai giới trong mọi kế hoạch quảng cáo'},
             {k:'c',t:'Vì họ phản hồi quảng cáo tốt hơn'},{k:'d',t:'Vì họ mua theo dịp dự đoán được, đơn giá cao — dễ nhắm đúng lúc'}],
    answer:'d', why:{a:'Không có căn cứ; giá trị cao ở đây là do dịp quà tặng, không do giới.',
      b:'Cân bằng giới không phải mục tiêu marketing.',
      c:'Không có dữ kiện về phản hồi quảng cáo.',
      d:'Đúng. Nhóm nhỏ nhưng biết trước lúc nào mua và mua gì thì rất dễ phục vụ hiệu quả.'} },
  { type:'mcq', stem:'Cách đọc báo cáo nhân khẩu học đúng nhất là gì?',
    options:[{k:'a',t:'Coi nó là nơi tìm người, còn phân khúc phải dựng từ dịp và nhu cầu'},{k:'b',t:'Coi nó là chân dung khách hàng đầy đủ và chính xác nhất mà thương hiệu có'},
             {k:'c',t:'Bỏ qua nó hoàn toàn vì luôn gây hiểu lầm'},{k:'d',t:'Chỉ tin nó khi mẫu trên 10.000 khách'}],
    answer:'a', why:{a:'Đúng. Nhân khẩu học giúp tìm và nhắm; nhu cầu và dịp giúp hiểu và quyết định.',
      b:'Nó thiếu lý do mua và dịp mua.',
      c:'Vẫn có ích để tìm người; bỏ hẳn là phí.',
      d:'Mẫu lớn vẫn không trả lời được "vì sao".'} }
  ] }

] });
